  --color-smoke: #c1c7cf;
  --color-ash: #9491a1;
  --color-slate: #615e6e;
  --color-charcoal: #333333;
  --color-carbon: #222222;
  --color-ink: #000000;

  /* Typography */
  --font-britti-sans: 'Britti Sans', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
